    arousalDysregulationWarning: 'DYSREGULATION',
    arousalCalibrationTitle: 'Your own comfort range',
    arousalCalibrationIntro:
      "The default range (0-55%) fits most people. But if your body already goes into alarm at small triggers, or you notice that \"calm\" for you actually means numbness, you can set your own, real limits here.",
    arousalExtendedModeLabel: 'Shifted window of tolerance (the slider recolors to match your range)',
    arousalCalibrationStart: 'Window start (%)',
